// Every place the rocket can land. Index 0 is Earth (home), 1..30 are the story planets in order,
// 31 is the abductors' mothership. Everything visual/gameplay about a planet hangs off this record.

function spiralPos(i, yScale = 14) {
  const r = 42 + i * 21, a = i * 0.82;
  return [Math.cos(a) * r, Math.sin(i * 0.9) * yScale, Math.sin(a) * r];
}

