// derived fields
const LAST = PLANETS.length - 1;
PLANETS.forEach((p, i) => {
  p.index = i;
  p.isHome = i === 0; p.isFinal = i === LAST;
  p.pos = i === 0 ? [0, 0, 0] : spiralPos(i, i === LAST ? 30 : 14);
  p.radius = i === 0 ? 7 : i === LAST ? 9 : 5 + ((i * 7) % 5) * 1.1;
  p.rating = i === 0 ? 60 : i === LAST ? 97 : Math.round(58 + i * 1.3);
  p.team.planetId = p.id;
});

export const PLANET_BY_ID = Object.fromEntries(PLANETS.map(p => [p.id, p]));
export const STORY_PLANETS = PLANETS.slice(1); // luna..mothership
export const distBetween = (a, b) => Math.hypot(a.pos[0] - b.pos[0], a.pos[1] - b.pos[1], a.pos[2] - b.pos[2]);
// Rocket range after collecting N parts: enough to reach planet N+1.
export function rangeForParts(n) {
  const target = PLANETS[Math.min(n + 1, PLANETS.length - 1)];
  return Math.hypot(...target.pos) + 8;
}
